<label>Location<input name="location" required></label><label>Condition<select name="condition_state"><option>GOOD</option><option>ACCEPTABLE</option><option>DAMAGED</option><option>CRITICAL</option></select></label><label>Runtime reading<input type="number" step="0.01" name="runtime_reading"></label><label>Mileage reading<input type="number" step="0.01" name="mileage_reading"></label><label class="check"><input type="checkbox" name="identity_verified" value="1" required> Equipment identity verified</label><label class="check"><input type="checkbox" name="accessories_verified" value="1" required> Package/accessories verified</label><label class="check"><input type="checkbox" name="condition_photographed" value="1" required> Condition captured</label><label>Photo/video evidence<input type="file" name="evidence" accept="image/jpeg,image/png,image/webp,video/mp4"></label><label>Owner signature<input name="owner_signature" required></label><label>Customer signature<input name="customer_signature" required></label><label class="full">Notes<textarea name="notes"></textarea></label>
